from durationkit import parse_duration

valid = {'90': 90.0, '  42 ': 42.0, '0007': 7.0, '2d': 172800.0, '500ms': 0.5, '1h30m': 5400.0, '1s500ms': 1.5, '1d1h1m1s1ms': 90061.001, '\t1h\n30m\r': 5400.0, '0d0h0m0s0ms': 0.0, '01h003m': 3780.0, '90m': 5400.0, '1500ms': 1.5}
for value, expected in valid.items():
    result = parse_duration(value)
    assert isinstance(result, float) and abs(result - expected) < 1e-9, (value, result)
invalid = ['', ' \t\n', '-1', '+1h', '1.5h', '1e3s', '1_000s', '1H', 'ms', '1h1h', '1ms2ms', '0s0s', '30m1h', '1ms1s', '0ms0s', '1 h', '1\tms', '1 0s', '9 0', '1h30', '90 1s', '1h,30m', '1h30m!', '1mss', '1h garbage', 'Ⅳ', 'Ⅳh', '½', '½s', '①', '①m']
for value in invalid:
    try:
        parse_duration(value)
    except ValueError:
        pass
    else:
        raise AssertionError(f'accepted {value!r}')
for value in [90, 1.5, None, True, b'90', []]:
    try:
        parse_duration(value)
    except TypeError:
        pass
    else:
        raise AssertionError(f'accepted non-string {value!r}')
